// Small local helper: place the ball below the field without importing the
// height (coverage intentionally light).
function belowField() {
  return 500;
}

// --- #1: brick bounce (ISSUES.md #1) ---------------------------------------

// One brick at a known place, away from the walls, to isolate the interaction.
function loneBrick(x = 300, y = 100) {
  return { x, y, w: 72, h: 20, row: 0, alive: true, points: 100 };
}

test('brick: bottom hit flips vy and leaves vx untouched', () => {
  const state = createState(1);
  const brick = loneBrick();
  state.bricks = [brick];
  state.ball = {
    x: brick.x + brick.w / 2,
    y: brick.y + brick.h + BALL_R + 1,
    r: BALL_R,
    vx: 7,
    vy: -200,
  };
  step(state, 1 / 60);
  assert.equal(Math.sign(state.ball.vy), DOWN, 'vy flips on a bottom hit');
  assert.equal(state.ball.vx, 7, 'vx is left exactly as it was');
  assert.equal(brick.alive, false);
  assert.ok(!collides(state.ball, brick), 'ball is pushed out of the brick');
  assert.equal(state.combo, 1);
  assert.ok(state.score > 0);
});

test('brick: side hit flips vx and leaves vy untouched', () => {
  const state = createState(1);
  const brick = loneBrick();
  state.bricks = [brick];
  state.ball = {
    x: brick.x - BALL_R - 1,
    y: brick.y + brick.h / 2,
    r: BALL_R,
    vx: 200,
    vy: 7,
  };
  step(state, 1 / 60);
  assert.equal(Math.sign(state.ball.vx), LEFT, 'vx flips on a side hit');
  assert.equal(state.ball.vy, 7, 'vy is left exactly as it was');
  assert.equal(brick.alive, false);
  assert.ok(!collides(state.ball, brick), 'ball is pushed out of the brick');
});

test('brick: exact corner hit flips both components', () => {
  const state = createState(1);
  const brick = loneBrick();
  state.bricks = [brick];
  state.ball = {
    x: brick.x - BALL_R - 18,
    y: brick.y - BALL_R - 18,
    r: BALL_R,
    vx: 1080,
    vy: 1080,
  };
  step(state, 1 / 60);
  assert.equal(Math.sign(state.ball.vx), LEFT, 'diagonal hit flips vx');
  assert.equal(Math.sign(state.ball.vy), UP, 'diagonal hit flips vy');
  assert.equal(brick.alive, false);
  assert.ok(!collides(state.ball, brick), 'ball is pushed out of the brick');
});

test('brick: push-out prevents a sticky re-flip on the next step', () => {
  const state = createState(1);
  const brick = loneBrick();
  state.bricks = [brick];
  state.ball = {
    x: brick.x + brick.w / 2,
    y: brick.y + brick.h + BALL_R + 2,
    r: BALL_R,
    vx: 0,
    vy: -300,
  };
  step(state, 1 / 60);
  assert.ok(!collides(state.ball, brick), 'ball no longer overlaps the brick');
  assert.equal(Math.sign(state.ball.vy), DOWN);
  const vyAfter = state.ball.vy;
  const yAfter = state.ball.y;
  step(state, 1 / 60); // moving away: must NOT flip again
  assert.equal(state.ball.vy, vyAfter, 'no re-flip while moving away');
  assert.equal(state.ball.vx, 0);
  assert.ok(state.ball.y > yAfter, 'ball keeps moving away from the brick');
});

test('brick: seam between two bricks bounces exactly once', () => {
  const state = createState(1);
  const a = loneBrick(200, 100);
  const b = loneBrick(200 + 72 + 8, 100); // 8 px gap, ball is 14 px across
  state.bricks = [a, b];
  state.ball = {
    x: 200 + 72 + 4, // riding the seam
    y: 100 + 20 + BALL_R + 2,
    r: BALL_R,
    vx: 0,
    vy: -300,
  };
  step(state, 1 / 60);
  assert.equal(a.alive, false, 'seam neighbour A breaks');
