// --- Physics (movement + wall/paddle/brick bounces) ------------------------

// Advances the ball by a time step `dt` (in seconds) and handles bounces off
// the walls, the paddle and the bricks. Brick collision is resolved by
// `bounceBricks()`: a sweep of the whole path with a per-face bounce and a
// push-out, so the ball can neither tunnel through a brick nor get stuck
// overlapping one (see ISSUES.md #1).
// Returns `true` if the ball is lost (exits through the bottom).
export function step(state, dt) {
  const { ball, paddle } = state;

  // Remember where the move started: the brick sweep needs the whole segment
  // (position before AND after the move) to catch fast balls (#1 tunnelling).
  const px = ball.x;
  const py = ball.y;
  ball.resolved = false; // frame() skips collision when step() handled it

  ball.x += ball.vx * dt;
  ball.y += ball.vy * dt;

