// Main render loop. Brick collision was historically resolved here, inside
// the draw pass (debt #2); since #1 it happens in `step()` via
// `bounceBricks()`, and this function only draws. When `frame()` is driven
// directly (e.g. in tests, without a preceding `step()`), it resolves on the
// spot so both entry points behave the same.
export function frame(ctx, state) {
  // Background
  ctx.fillStyle = palette.background;
  ctx.fillRect(0, 0, WIDTH, HEIGHT);

